import { Buffer } from 'node:buffer'
import { readFile, writeFile } from 'node:fs/promises'
import process from 'node:process'

const directory = new URL('../src/components/weather-bottle/', import.meta.url)
const [css, markup, script] = await Promise.all(['scene.css', 'markup.html', 'scene.js'].map(name => readFile(new URL(name, directory), 'utf8')))
const target = new URL('../public/widgets/weather-bottle/index.html', import.meta.url)
const html = `<!doctype html>
<!-- Generated by pnpm build:weather from src/components/weather-bottle/. Do not edit this copy. -->
<html lang="zh-CN">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<meta name="color-scheme" content="light dark" />
<title>装着天气的玻璃瓶 · A bottle of weather</title>
<style>body { margin: 0; }\n${css}</style>
</head>
<body>
<div class="weather-scene" data-weather-scene>${markup}</div>
<script type="module">
${script.replace('export function mountWeatherBottle', 'function mountWeatherBottle')}
const params = new URLSearchParams(location.search);
const host = document.querySelector('[data-weather-scene]');
let current;
function mount() {
  current?.dispose();
  current = mountWeatherBottle(host, {
    locale: params.get('lang') || 'zh',
    dark: params.has('theme') ? params.get('theme') === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches,
    live: params.get('live') === '1',
    debug: params.get('debug') === '1',
    onRetry: mount,
  });
}
mount();
</script>
</body>
</html>
`
if (process.argv.includes('--check')) {
  if (await readFile(target, 'utf8') !== html)
    throw new Error('Standalone weather bottle is out of date. Run pnpm build:weather.')
  console.log('Standalone HTML matches the shared component source.')
}
else {
  await writeFile(target, html)
  console.log(`Generated ${Buffer.byteLength(html)} byte standalone weather bottle.`)
}
